def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the centered, uniform separator.
    split = None
    orientation = None
    if w % 2 == 1:
        c = w // 2
        if all(row[c] == grid[0][c] for row in grid):
            split, orientation = c, "vertical"
    if split is None and h % 2 == 1:
        r = h // 2
        if all(v == grid[r][0] for v in grid[r]):
            split, orientation = r, "horizontal"

    if orientation == "vertical":
        a = [row[:split] for row in grid]
        b = [row[split + 1:] for row in grid]
    else:
        a = grid[:split]
        b = grid[split + 1:]

    counts_a = {}
    counts_b = {}
    for row in a:
        for v in row:
            counts_a[v] = counts_a.get(v, 0) + 1
    for row in b:
        for v in row:
            counts_b[v] = counts_b.get(v, 0) + 1

    shared = set(counts_a) & set(counts_b)
    base = max(shared, key=lambda v: counts_a[v] + counts_b[v])

    return [
        [3 if a[r][c] == base and b[r][c] == base else base
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
